mapper.select:
SELECT u.*, t.tenant_name as tenantName, t.short_code as shortName FROM sys_user u LEFT JOIN sys_tenant t ON u.tenant_id = t.id WHERE u.deleted = 0
AND u.tenant_id = #{tenantId}
AND u.dept_id = #{deptId}
AND u.status = #{status}
AND ( u.real_name LIKE CONCAT('%', #{keyword}, '%') OR u.username LIKE CONCAT('%', #{keyword}, '%') OR u.phone LIKE CONCAT('%', #{keyword}, '%') OR t.tenant_name LIKE CONCAT('%', #{keyword}, '%') or t.short_code LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY u.updated_at DESC
